    // _`addHistoryScrubber`
    // ---------------------
    // Activecode -- If the code has not changed wrt the scrubber position value then don't save the code or reposition the scrubber
    //  -- still call runlog, but add a parameter to not save the code
    // add an initial load history button
    // if there is no edit then there is no append   to_save (True/False)
    async addHistoryScrubber(pos_last) {
        this.addingScrubber = true;
        let response;
        var reqData = {
            acid: this.divid,
        };
        if (this.sid !== undefined) {
            reqData["sid"] = this.sid;
        }
        console.log("before get hist");
        if (
            eBookConfig.practice_mode ||
            !eBookConfig.isLoggedIn ||
            (this.isTimed && !this.assessmentTaken)
        ) {
            // If this is timed and already taken we should restore history info
            this.renderScrubber();
        } else {
            let request = new Request(
                `${eBookConfig.new_server_prefix}/assessment/gethist`,
                {
                    method: "POST",
                    headers: this.jsonHeaders,
                    body: JSON.stringify(reqData),
                },
            );
            try {
                response = await fetch(request);
                let data = await response.json();
                if (!response.ok) {
                    throw new Error(
                        `Failed to get the history data: ${data.detail}`,
                    );
                }
                data = data.detail;
                if (data.history !== undefined) {
                    this.history = this.history.concat(data.history);
                    for (let t in data.timestamps) {
                        this.timestamps.push(
                            new Date(data.timestamps[t]).toLocaleString(),
                        );
                    }
                }
            } catch (e) {
                console.log(`unable to fetch history: ${e}`);
            }
            this.renderScrubber(pos_last);
        }
        this.addingScrubber = false;
        return "success";
    }

    renderScrubber(pos_last) {
        console.log("making a new scrubber");
        var scrubberDiv = document.createElement("div");
        scrubberDiv.classList.add("ac_history_scrubber_box");
        scrubberDiv.style.display = "inline-block";
        scrubberDiv.style.marginLeft = "10px";
        scrubberDiv.style.marginRight = "10px";
        scrubberDiv.style.minWidth = "200px";
        scrubberDiv.style.maxWidth = "300px";
        // A native range input replaces the old jQuery UI slider.
        var scrubber = document.createElement("input");
        scrubber.type = "range";
        scrubber.min = 1;
        scrubber.max = this.history.length;
        scrubber.value = this.history.length;
        scrubber.step = 1;
        scrubber.classList.add("ac_history_scrubber");
        scrubber.setAttribute("aria-label", "History slider");
        this.timestampP = document.createElement("span");
        const updateStatus = (pos) => {
            const status = `${this.timestamps[pos]} - ${pos + 1} of ${
                this.history.length
            }`;
            this.timestampP.textContent = status;
            // The native range value is a position; expose the matching
            // visible revision and timestamp as its accessible value.
            scrubber.setAttribute("aria-valuetext", status);
        };
        this.slideit = function (ev) {
            let pos = Number(scrubber.value) - 1;
            let submittedCode = this.history[pos];
            let code = this.readdLockedCode(submittedCode);
            this.editor.setValue(code);
            this.setLockedRegions();
            var curVal = this.timestamps[pos];
            updateStatus(pos);
            // "input" events fire continuously while dragging; only log once
            // the position settles (the "change" event, or a programmatic
            // call passing null).
            if (ev !== null && ev.type != "input") {
                this.logBookEvent({
                    event: "activecode",
                    act: "slide:" + curVal,
                    div_id: this.divid,
                });
            }
            this.setHighlightLines();
        };
        scrubber.style.margin = "10px";
        scrubber.addEventListener("input", this.slideit.bind(this));
        scrubber.addEventListener("change", this.slideit.bind(this));
        scrubberDiv.appendChild(scrubber);
        scrubberDiv.appendChild(this.timestampP);
        // If there is a deadline set then position the scrubber at the last submission
        // prior to the deadline
        if (this.deadline) {
            let i = 0;
            let done = false;
            while (i < this.history.length && !done) {
                if (new Date(this.timestamps[i]) > this.deadline) {
                    done = true;
                } else {
                    i += 1;
                }
            }
            i = i - 1;
            scrubber.value = Math.max(i, 0) + 1;
            let submittedCode = this.history[Number(scrubber.value) - 1];
            let code = this.readdLockedCode(submittedCode);
            this.editor.setValue(code);
            this.setLockedRegions();
        } else if (pos_last) {
            scrubber.value = this.history.length;
            let submittedCode = this.history[Number(scrubber.value) - 1];
            let code = this.readdLockedCode(submittedCode);
            this.editor.setValue(code);
            this.setLockedRegions();
        } else {
            scrubber.value = 1;
        }
        this.setHighlightLines();
        let pos = Number(scrubber.value) - 1;
        updateStatus(pos);
        this.historyScrubber = scrubber;
        this.runButton.insertAdjacentElement("afterend", scrubberDiv);
    } // end definition of helper

